    static String forScene(Scene scene){
        try{
            String[] list=scene.id.startsWith("C")?C:scene.id.startsWith("N")?N:scene.id.startsWith("O")?O:scene.id.startsWith("S")?S:null;
            int i=Integer.parseInt(scene.id.substring(1))-1;
            if(list!=null&&i>=0&&i<list.length)return list[i];
        }catch(Exception ignored){}
        return WorldStore.NO_ARABIC;
    }
